// Isolated Canvas transport test. PRIVATE_PAYLOAD_DIR contains real Paula67
// Dashboard output JSON generated by fixture_canvas_real_payloads.R.
// Other IDs use an explicitly labelled transport image, NOT scientific data.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {execFileSync}=require('node:child_process');
const {chromium}=require('../../browser/ci/node_modules/playwright');
const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
(async()=>{
 const browser=await chromium.launch({headless:true});const results=[];
 try{
 const page=await browser.newPage();page.setDefaultTimeout(5000);
 await page.setContent(`<div id="analysis"></div><section id="team-canvas-root"><input class="tc-search"><div class="tc-list"></div><button class="tc-reset"></button><button class="tc-arrange"></button><button class="tc-library-toggle"></button><div class="tc-layout"><div class="tc-board"><div class="tc-empty"></div></div><div class="tc-status"></div></div></section><script>window.routes=[];window.Shiny={setInputValue:(n,v)=>routes.push([n,v])};</script>`);
 await page.addStyleTag({path:path.resolve('www/team/css/canvas.css')});
 for(const [pkg,rel] of [['shiny','www/shared/jquery.min.js'],['plotly','htmlwidgets/lib/plotlyjs/plotly-latest.min.js']])await page.addScriptTag({path:execFileSync('Rscript',['--vanilla','-e',`cat(system.file("${rel}",package="${pkg}"))`],{encoding:'utf8'}).trim()});
 await page.addScriptTag({path:path.resolve('www/team/js/canvas_catalog.js')});
 await page.addScriptTag({path:path.resolve('www/team/js/canvas.js')});
 const dynamicUI=fs.existsSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,'dynamic-source-ui.json'))?JSON.parse(fs.readFileSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,'dynamic-source-ui.json'))):{};
 const catalog=await page.evaluate(()=>TeamCanvasCatalog.list);assert.equal(catalog.length,56);
 // First exercise every absent-output route, without mounting fabricated analysis.
 for(const item of catalog){
  await page.evaluate(id=>{const card=Array.from(document.querySelectorAll('[data-catalog-id]')).find(x=>x.dataset.catalogId===id);const entry=TeamCanvasCatalog.get(id);const button=Array.from(card.querySelectorAll('button')).find(x=>x.textContent===(entry.routeOnly?entry.routeOnly.action:'Add'));if(!button)throw Error('Missing route '+id);button.click();},item.id);
  const route=await page.evaluate(()=>routes.at(-1));const expected=item.route.startsWith('step:')?['guide_step',Number(item.route.slice(5))]:item.route.startsWith('input:')?null:['guide_open_tool',item.route];if(expected)assert.deepEqual(route,expected);else assert.equal(route[0],item.route.slice(6));
  if(!item.routeOnly)await page.evaluate(id=>document.querySelector('[data-catalog-id="'+id+'"] button').click(),item.id);
  results.push({id:item.id,route:'PASS',transport_payload:'labelled mechanical image',scientific_result:'see separate coverage matrix'});
 }
 await page.evaluate(()=>window.dispatchEvent(new CustomEvent('team-preparation-state',{detail:{ready:true,pending:false,running:false,revision:1}})));
 for(const row of results){
  const id=row.id,qcJSON=fs.existsSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,row.id+'.json'))&&!row.id.startsWith('cell_'),qcPNG=fs.existsSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,row.id+'.png')),dashboard=id.startsWith('results_dashboard-plot_'),cell=id.startsWith('cell_'),real=dashboard||cell||qcJSON,network=id==='pathway_tab-pathwayVisNetwork';
  if(dashboard||cell){
   const html=fs.readFileSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,dashboard?'dashboard-ui.html':'cell-ui.html'),'utf8');
   const dynamic=cell?fs.readFileSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,'cell-class-ui.html'),'utf8'):null;
   await page.evaluate(({html,dynamic})=>{document.getElementById('analysis').innerHTML=html;if(dynamic)document.getElementById('cell_class_plot_ui').innerHTML=dynamic;},{html,dynamic});
   row.source_wrapper='production UI function HTML'+(id==='cell_class_plot'?' plus real renderUI wrapper':'');
   const filename=dashboard?id.split('plot_')[1]+'.json':id+'.json';
   const payload=JSON.parse(fs.readFileSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,filename)));
   await page.evaluate(async({id,p})=>{await Plotly.newPlot(id,p.x.data,p.x.layout,p.x.config);},{id,p:payload});row.transport_payload='actual configured Paula67 serialized Plotly';
  }else{
   const sourceFile=fs.readdirSync(process.env.PRIVATE_PAYLOAD_DIR).filter(f=>f.startsWith('source-ui-')&&f.endsWith('.html')).find(f=>{const html=fs.readFileSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,f),'utf8');return html.includes('id="'+id+'"')||Object.entries(dynamicUI).some(([parent,inner])=>html.includes('id="'+parent+'"')&&inner.includes('id="'+id+'"'));});
   if(sourceFile){const html=fs.readFileSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,sourceFile),'utf8');await page.evaluate(({html,dynamicUI})=>{document.getElementById('analysis').innerHTML=html;Object.entries(dynamicUI).forEach(([parent,inner])=>{const el=document.getElementById(parent);if(el)el.innerHTML=inner;});},{html,dynamicUI});row.source_wrapper='production UI function HTML '+sourceFile+(Object.values(dynamicUI).some(x=>x.includes('id="'+id+'"'))?' plus input-only production renderUI':'');}
   else{await page.evaluate(({id,network})=>{const el=document.createElement('div');el.id=id;el.className=network?'html-widget-output':'shiny-plot-output';el.style.cssText='height:420px;width:640px';document.getElementById('analysis').append(el);}, {id,network});row.source_wrapper='synthetic safe mount; not actual module wrapper';}
   if(qcJSON){const payload=JSON.parse(fs.readFileSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,id+'.json')));await page.evaluate(async({id,p})=>{const el=document.getElementById(id);el.className='plotly html-widget-output';await Plotly.newPlot(id,p.x.data,p.x.layout,p.x.config);},{id,p:payload});row.transport_payload='actual configured Paula67 QC serialized Plotly';}
   else if(qcPNG){const image=fs.readFileSync(path.join(process.env.PRIVATE_PAYLOAD_DIR,id+'.png')).toString('base64');await page.evaluate(({id,image})=>{const img=new Image();img.src='data:image/png;base64,'+image;document.getElementById(id).append(img);},{id,image});row.transport_payload='actual configured Paula67 PNG';}
   else if(!network){
    const guided=id==='qc_pca_tab-guided_qc_plot'&&process.env.GUIDED_QC_SVG;
    const svg=guided?fs.readFileSync(process.env.GUIDED_QC_SVG,'utf8'):'<svg xmlns="http://www.w3.org/2000/svg" width="640" height="420"><rect width="640" height="420" fill="white"/><text x="20" y="40">Mechanical transport fixture only</text></svg>';
    await page.evaluate(({id,svg})=>{const image=new Image();image.src='data:image/svg+xml,'+encodeURIComponent(svg);document.getElementById(id).append(image);},{id,svg});
    if(guided)row.transport_payload='actual previously browser-exported Paula67 guided QC SVG';
   }
  }
  if(catalog.find(x=>x.id===id).routeOnly){
   assert.equal(await page.evaluate(id=>TeamCanvas.addCatalogPlot(id),id),false);assert.equal(await page.evaluate(id=>TeamCanvas.queuePlot(id),id),false);row.add='DEDICATED_EXPORT_ROUTE';row.finish='DEDICATED_EXPORT_ROUTE';
   await page.locator('[data-catalog-id="'+id+'"]').getByRole('button',{name:'Open export studio',exact:true}).click();assert.equal(await page.evaluate(()=>routes.at(-1)[0]),'guide_export_studio');row.exclusion_and_route='PASS';
   await page.evaluate(()=>document.getElementById('analysis').replaceChildren());continue;
  }
  try{await page.waitForFunction(id=>{const p=TeamCanvas.listPlots().find(x=>x.id===id),b=document.querySelector('[data-catalog-id="'+id+'"] button');return p?.available||b?.textContent==='Open analysis';},id);}catch(e){throw Error(id+' discovery: '+JSON.stringify(await page.evaluate(id=>({html:document.getElementById(id)?.outerHTML.slice(0,300),card:document.querySelector('[data-catalog-id="'+id+'"]')?.textContent}),id)));}
  const added=await page.evaluate(id=>TeamCanvas.addCatalogPlot(id),id);
  if(!added&&row.source_wrapper.startsWith('production')){
   row.add='SAFE_ROUTE_ONLY';row.finish='SAFE_ROUTE_ONLY';
   const card=page.locator('[data-catalog-id="'+id+'"]');await card.getByRole('button',{name:'Open analysis',exact:true}).click();row.wrapper_guard='PASS';
   await page.evaluate(()=>document.getElementById('analysis').replaceChildren());continue;
  }
  assert.equal(added,true,id+' must add or explicitly expose an unsafe-wrapper route');row.add='PASS';
  await page.evaluate(id=>{const el=document.getElementById(id);jQuery(el).trigger('shiny:value');const img=el.querySelector('img');if(img)img.src=img.src+'#rendered';},id);
  await page.waitForTimeout(850);
  const node=page.locator('.tc-node');assert.equal(await node.count(),1);
  if(network){assert.equal(await node.getByRole('button',{name:'Live only',exact:true}).isDisabled(),true);row.finish='LIVE_ONLY_EXPLICIT';}
  else{
   await node.getByRole('button',{name:'Finish plot',exact:true}).click();try{await page.waitForSelector('.tc-snapshot img');}catch(e){throw Error(id+': '+await page.locator('.tc-status').textContent());}row.finish='PASS';
   assert.ok((await page.locator('.tc-snapshot img').getAttribute('src')).startsWith(real?'data:image/svg+xml':'data:image/png'));
   await node.getByRole('button',{name:'Edit',exact:true}).click();
   await page.evaluate(id=>jQuery(document.getElementById(id)).trigger('shiny:error'),id);
   await node.getByRole('button',{name:'Finish plot',exact:true}).click();assert.equal(await page.locator('.tc-snapshot').count(),0);
   assert.match(await page.locator('.tc-status').textContent(),/Wait for preparation.*plot.*finish updating/);row.error_guard='PASS';
  }
  await node.getByRole('button',{name:'Return',exact:true}).click();assert.equal(await page.locator('#analysis [id="'+id+'"]').count(),1);row.return='PASS';
  await page.evaluate(()=>document.getElementById('analysis').replaceChildren());
 }
 const report={status:'PASS',scope:'isolated Chromium; current local production JS; no live-session claim',source_hashes:Object.fromEntries(['www/team/js/canvas.js','www/team/js/canvas_catalog.js'].map(p=>[p,sha(p)])),counts:{registered:56,routes:56,add_return:results.filter(r=>r.return==='PASS').length,finish:results.filter(r=>r.finish==='PASS').length,live_only:results.filter(r=>r.finish==='LIVE_ONLY_EXPLICIT').length,error_guard:results.filter(r=>r.error_guard==='PASS').length,unsafe_wrapper_route_only:results.filter(r=>r.add==='SAFE_ROUTE_ONLY').length,dedicated_export_route:results.filter(r=>r.add==='DEDICATED_EXPORT_ROUTE').length,actual_Paula67_Plotly_capture:results.filter(r=>r.transport_payload.includes('Plotly')).length,actual_Paula67_PNG_capture:results.filter(r=>r.transport_payload.includes('PNG')).length,actual_Paula67_existing_SVG_capture:process.env.GUIDED_QC_SVG?1:0,production_UI_wrapper:results.filter(r=>r.source_wrapper.startsWith('production')).length,mechanical_image_capture:results.filter(r=>r.transport_payload==='labelled mechanical image'&&r.finish==='PASS').length},limitations:['Production UI function HTML where available; unresolved dynamic outputs remain synthetic mounts. Module UI replay excludes outer live Shiny app ancestors.','Configured Dashboard/cell/QC payloads and optional previously browser-exported guided QC SVG; other captures are mechanical.','Missing-input and inference gate messages are validated separately in R; mechanical image capture is not scientific validation.','No live browser, all-setting, or universal parity claim.'],results};
 if(process.env.CANVAS_CATALOG_JSON)fs.writeFileSync(process.env.CANVAS_CATALOG_JSON,JSON.stringify(report,null,2));console.log(JSON.stringify(report.counts));
 }finally{await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
